import nbformat as nbf

# %% ../nbs/epx.ipynb #adc77fd1
@patch
def to_nbs(self:Epx, dest:str='nbs'):
    "Export each spine section as a separate notebook under `dest`, with the book's images at their EPUB paths."
    dest = Path(dest)
    dest.mkdir(exist_ok=True)
    for i, sid in enumerate(self.spine_ids):
        href = self.manifest[sid]['href']
        label = self._toc_labels.get(href, href)
        nb = nbf.v4.new_notebook()
        nb.cells = [nbf.v4.new_markdown_cell(t) for t in self.section(i).split('\n\n')]
        slug = re.sub(r'[^a-z0-9]+', '_', label.lower()).strip('_')
        nbf.write(nb, str(dest / f'{i:03d}_{slug}.ipynb'))
    for o in self.images():
        p = dest/o
        p.parent.mkdir(parents=True, exist_ok=True)
        p.write_bytes(self._zip_read(o))

# %% ../nbs/epx.ipynb #96ef014f
@call_parse
def epx(
    section:int=None, # Spine section to print
    epub:str=None, # EPUB path; otherwise use automatic discovery
    to_nbs:str=None, # Export notebooks to this directory instead of printing
):
    "Read EPUB sections or export them as notebooks."
    book = Epx(epub)
    if to_nbs is not None: book.to_nbs(to_nbs)
    elif section is not None: print(book.section(section))
    else: print(book.toc())
